-- Online operations and finance expansion. See applied schema for complete definitions.
create table if not exists public.member_documents(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,member_id uuid not null references public.members(id) on delete cascade,document_type text not null,file_name text not null,storage_path text not null,mime_type text,file_size_bytes bigint,verified_at timestamptz,verified_by uuid references auth.users(id),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.family_relationships(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,family_id uuid not null references public.families(id) on delete cascade,member_id uuid not null references public.members(id) on delete cascade,relationship text not null,is_primary_contact boolean not null default false,created_at timestamptz not null default now(),unique(family_id,member_id));
alter table public.attendance_records add column if not exists event_id uuid references public.church_events(id) on delete set null;
alter table public.attendance_records add column if not exists visitor_phone text;
alter table public.attendance_records add column if not exists attendance_status text not null default 'present';
alter table public.attendance_records add column if not exists checked_in_by uuid references auth.users(id);
create table if not exists public.pastoral_followups(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,request_id uuid not null references public.pastoral_requests(id) on delete cascade,due_at timestamptz,completed_at timestamptz,assigned_to uuid references auth.users(id),followup_notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.chart_of_accounts(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,account_code text not null,account_name text not null,account_type text not null check(account_type in ('asset','liability','equity','income','expense')),parent_id uuid references public.chart_of_accounts(id) on delete set null,is_active boolean not null default true,created_at timestamptz not null default now(),unique(church_id,account_code));
create table if not exists public.journal_entries(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,entry_number text not null,entry_date date not null default current_date,description text not null,status text not null default 'draft' check(status in ('draft','posted','reversed')),source_type text,source_id uuid,created_by uuid references auth.users(id),posted_by uuid references auth.users(id),posted_at timestamptz,created_at timestamptz not null default now(),unique(church_id,entry_number));
create table if not exists public.journal_lines(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,journal_entry_id uuid not null references public.journal_entries(id) on delete cascade,account_id uuid not null references public.chart_of_accounts(id),description text,debit numeric(14,2) not null default 0 check(debit>=0),credit numeric(14,2) not null default 0 check(credit>=0),currency_code char(3) not null default 'PKR',check((debit>0 and credit=0) or (credit>0 and debit=0)));
create table if not exists public.financial_budgets(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,name text not null,fiscal_year integer not null,currency_code char(3) not null default 'PKR',status text not null default 'draft' check(status in ('draft','approved','closed')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(church_id,name,fiscal_year));
create table if not exists public.financial_budget_lines(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,budget_id uuid not null references public.financial_budgets(id) on delete cascade,account_id uuid not null references public.chart_of_accounts(id),period_month integer not null check(period_month between 1 and 12),planned_amount numeric(14,2) not null default 0 check(planned_amount>=0),unique(budget_id,account_id,period_month));
create table if not exists public.asset_maintenance(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,asset_id uuid not null references public.church_assets(id) on delete cascade,maintenance_date date not null default current_date,description text not null,cost numeric(14,2) not null default 0 check(cost>=0),next_due_date date,performed_by text,created_at timestamptz not null default now());
create table if not exists public.donation_pledges(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,donor_name text not null,member_id uuid references public.members(id) on delete set null,amount numeric(14,2) not null check(amount>0),currency_code char(3) not null default 'PKR',pledged_on date not null default current_date,due_on date,status text not null default 'open' check(status in ('open','partially_paid','fulfilled','cancelled')),notes text,created_at timestamptz not null default now());
create table if not exists public.audit_exports(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,requested_by uuid not null references auth.users(id),export_type text not null,storage_path text,status text not null default 'requested' check(status in ('requested','ready','failed','expired')),created_at timestamptz not null default now(),expires_at timestamptz);
do $$ declare t text; begin foreach t in array array['member_documents','family_relationships','pastoral_followups','chart_of_accounts','journal_entries','journal_lines','financial_budgets','financial_budget_lines','asset_maintenance','donation_pledges','audit_exports'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists %I on public.%I',t||'_church_staff_access',t); execute format('create policy %I on public.%I for all to authenticated using (private.has_church_role(church_id,array[''owner'',''admin'',''pastor'',''finance'',''staff''])) with check (private.has_church_role(church_id,array[''owner'',''admin'',''pastor'',''finance'',''staff'']))',t||'_church_staff_access',t); end loop; end $$;
create index if not exists attendance_records_church_checkin_idx on public.attendance_records(church_id,check_in_at desc);
create index if not exists pastoral_followups_due_idx on public.pastoral_followups(church_id,due_at) where completed_at is null;
create index if not exists journal_entries_church_date_idx on public.journal_entries(church_id,entry_date desc);
create index if not exists member_documents_member_idx on public.member_documents(church_id,member_id);
